def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    # Parse events and collect segments of visitors
    segments = []
    current_segment = set()

    for i in range(1, len(lines)):
        parts = lines[i].split()
        if parts[0] == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = set()
        elif len(parts) >= 2:
            current_segment.add(parts[1])

    if current_segment:
        segments.append(current_segment)

    if not segments:
        return '0'

    # Map friend names to indices 0 to m_actual-1
    all_friends = set()
    for seg in segments:
        all_friends.update(seg)

    name_to_idx = {name: i for i, name in enumerate(all_friends)}
    m_actual = len(all_friends)

    if m_actual == 0 or m_actual > 40:
        return '0'

    # Build conflict graph where edge exists if two friends appear in same segment
    conflict = [[False] * m_actual for _ in range(m_actual)]
    for seg in segments:
        if len(seg) > 1:
            friends = [name_to_idx[n] for n in seg]
            for i in range(len(friends)):
                for j in range(i + 1, len(friends)):
                    conflict[friends[i]][friends[j]] = True
                    conflict[friends[j]][friends[i]] = True

    # Maximum Independent Set using branch and bound
    best = [0]

    def count_set_bits(mask):
        c = 0
        while mask:
            mask &= mask - 1
            c += 1
        return c

    def max_independent_set(available_mask, current_count):
        nonlocal best

        # Pruning: if we can't possibly beat the best, stop
        if current_count + count_set_bits(available_mask) <= best[0]:
            return

        # Base case: no vertices left to consider
        if available_mask == 0:
            best[0] = max(best[0], current_count)
            return

        # Pick the vertex with smallest index in available_mask
        v = available_mask & -available_mask
        v_idx = (v.bit_length() - 1) if v.bit_length() > 0 else 0

        # Option 1: Don't include vertex v (try to include others)
        other_available = available_mask ^ v
        max_independent_set(other_available, current_count)

        # Option 2: Include vertex v (exclude neighbors)
        neighbors_mask = v
        for u in range(m_actual):
            if conflict[v_idx][u]:
                neighbors_mask |= (1 << u)
        new_available = available_mask & ~neighbors_mask
        max_independent_set(new_available, current_count + 1)

    full_mask = (1 << m_actual) - 1
    max_independent_set(full_mask, 0)

    return str(best[0])

def sum_digits_range(l, r):
    """Helper function to compute sum of digits from l to r."""
    def sum_digits(n):
        s = 0
        while n > 0:
            s += n % 10
            n //= 10
        return s

    total = 0
    for i in range(l, r + 1):
        total += sum_digits(i)
    return total

