            is_prime_small = bytearray([1]) * (limit + 1)
            is_prime_small[0] = 0
            is_prime_small[1] = 0

            before_limit = int(math.isqrt(limit))
            for i in range(2, before_limit + 1):
                if is_prime_small[i]:
                    for j in range(i * i, limit + 1, i):
                        is_prime_small[j] = 0

            base_primes = [i for i in range(limit + 1) if is_prime_small[i]]

        is_prime = bytearray([1]) * (seg_end - seg_start + 1)
        seg_size = seg_end - seg_start + 1

        for p in base_primes:
            if p * p > r:
                break
            # First multiple of p greater than or equal to seg_start
            first_multiple = ((seg_start // p) + 1) * p
            if first_multiple < p * p:
                first_multiple = p * p
            for j in range(first_multiple, seg_end + 1, p):
                if j >= l and j <= r and j >= seg_start and j < seg_end:
                    is_prime[j - seg_start] = 0
                elif j >= seg_start and j < seg_end:
                    pass

        # Handle primes less than l manually
