                continue
            idx = i - seg_start
            if is_prime[idx]:
                if i == 2 or i % 4 == 1:
                    count += 1
    else:
        # Segmented sieve for large range
        count = 0
        seg_size = min(50000, r - l + 1)
        current = l

        while current <= r:
            seg_end = min(current + seg_size - 1, r)
            seg_size_actual = seg_end - current + 1

            is_prime = bytearray([1]) * seg_size_actual

            for p in base_primes:
                if p * p > seg_end:
                    break
                first = ((current + p - 1) // p) * p
                if first < p * p:
