                # Check if solution is valid (pairwise coprime)
                if is_coprime_pairwise(current_b):
                    if current_budget <= best_budget:
                        best_solution = current_b.copy()
                        best_budget = current_sum_sq
                return

            # Try values for b[idx]
            for val in possible[idx]:
                # Check pairwise coprimality
                valid = True
                sum_c = 0
                for prev in current_b:
                    if gcd(val, prev) != 1:
                        valid = False
                        break
                    sum_c += val * val

                if valid and sum_c <= best_budget:
