    MOD = 998244353

    # Precompute factorials
    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Precompute derangements D[n] = number of permutations where p[i] != i
    D = [0] * (n + 1)
    D[0] = 1
    D[1] = 0
    for i in range(2, n + 1):
        D[i] = (i - 1) * (D[i - 1] + D[i - 2]) % MOD

    total = 0

    # Count valid rows for row 0 that are lexicographically smaller than mat[0]
    # Row 0 has no vertical constraints, so any permutation of [1,n] is valid
    used = [False] * (n + 1)
    for j in range(n):
        target = mat[0][j]
        # Count how many unused values are smaller than target[j]
        smaller = sum(1 for v in range(1, target) if not used[v])
        if smaller > 0:
            total = (total + smaller * fact[n - 1 - j]) % MOD
        used[target] = True

