        """Count valid permutations of [1,n] that are < target and diff from prev at each position"""
        import itertools
        cnt = 0
        for perm in itertools.permutations(range(1, n + 1)):
            row = list(perm)
            valid = True
            for j in range(n):
                if row[j] == prev[j]:
                    valid = False
