    else:
        def is_valid_row(prev, current):
            for j in range(n):
                if current[j] == prev[j]:
                    return False
            return True

    # Process rows 1 to n-1
    for i in range(1, n):
        prev_row = mat[i - 1]
        curr_target = mat[i]

        if n <= 5:
            # For small n, enumerate all permutations and count
            cnt = 0
            for perm in range(1, n + 1):
