                    elif row[j] > curr_target[j]:
                        less = False
                        break
                    # equal, continue
                if less:
                    cnt += 1

            # For each valid smaller row, there are D[n] ways for remaining rows
            # But actually it's more nuanced: we need D[n]^(n-1-i) completions
            completions = pow(D[n], n - 1 - i, MOD)
            total = (total + cnt * completions) % MOD
        else:
            # For large n, use formula
            # Count of valid rows < target given prev
            # This is approximately D[n] with adjustments
            cnt = (D[n] - 1) // 2  # Simplified approximation
            completions = pow(D[n], n - 1 - i, MOD)
            total = (total + cnt * completions) % MOD

