    val_to_idx = {val: i for i, val in enumerate(p)}

    # Union-find to track elements that must be in the same set
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Build unions: if x can go to A, then (a-x) must also be in A
    # This means both x and (a-x) are connected
    for i in range(n):
        val = p[i]
        if (a - val) in val_to_idx:
            other_idx = val_to_idx[a - val]
            union(i, other_idx)

    # Group by component
    components = defaultdict(list)
    for i in range(n):
        root = find(i)
        components[root].append(i)

    # For each component, determine if it can go to A, B, or both
    component_assignment = {}
    possible = True

