def solution(input_str):
    n, m = map(int, input_str.split())

    # Ensure n <= m for easier processing
    if n > m:
        n, m = m, n

    # Case 1: n = 1 (1D line)
    if n == 1:
        if m < 3:
            return "0"
        else:
            return str(2 * (m // 3))

    # Case 2: n = 2
    if n == 2:
        if m == 2:
            return "0"
        else:
            # For 2×m where m ≥ 3
            return str(2 * m - 2)

    # Case 3: n ≥ 3 (2D grid with sufficient dimensions)
    # If n*m is odd, we lose 1 cell; otherwise use all cells
    if (n * m) % 2 == 1:
        return str(n * m - 1)
    else:
        return str(n * m)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    heights = list(map(int, lines[1].split()))

    result = 0
    for i in range(n):
        for j in range(i + 1, n):
            max_h = max(heights[i], heights[j])

            clockwise_blocked = False
            curr = (i + 1) % n
            while curr != j:
                if heights[curr] > max_h:
                    clockwise_blocked = True
                    break
                curr = (curr + 1) % n

            counter_blocked = False
            curr = (i - 1) % n
            while curr != j:
                if heights[curr] > max_h:
                    counter_blocked = True
                    break
                curr = (curr - 1) % n

            if not clockwise_blocked or not counter_blocked:
                result += 1

    return str(result)

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    g, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return g, x, y

def inverse(a, p):
    g, x, y = extended_gcd(a % p, p)
    if g != 1:
        return None
    return (x % p + p) % p

def factorials():
