    global fact, invFact
    MAX_N = 100005
    fact = [1] * MAX_N
    invFact = [1] * MAX_N
    for i in range(2, MAX_N):
        fact[i] = (fact[i-1] * i) % MOD
    invFact[MAX_N - 1] = inverse(fact[MAX_N - 1], MOD)
    for i in range(MAX_N - 2, 1, -1):
        invFact[i] = (invFact[i + 1] * (i + 1)) % MOD

n, p, l, r = map(int, " ".join(input().split()))

