invFact = [1] * (n + 1)
invFact[n] = invFactMax
for i in range(n - 1, 0, -1):
    invFact[i] = (invFact[i + 1] * (i + 1)) % MOD

def binom(n, k):
    if k < 0 or k > n:
        return 0
    num = fact[n]
    den = (invFact[k] * invFact[n - k]) % MOD
    return (num * den) % MOD

ans = 0
for k in range(l, min(r, n) + 1):
