        if a == 0:
            way = 1 if b == 0 else 0
        else:
            ways_ab = fact[a + b]
            den = ((invFact[b] * invFact[a]) % MOD * inverse(a + 1)) % MOD
            ways_ab = (ways_ab * den) % MOD

        ans = (ans + binom(n, c) * ways_ab) % MOD

return str(ans)

