    lines = input_str.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1

    results = []

    for _ in range(t):
        # Skip empty lines
        while idx < len(lines) and lines[idx].strip() == '':
            idx += 1
        idx += 1  # Move past the empty line

        n = int(lines[idx])
        idx += 1

        # Read nodes
        values = [None] * n  # value when reduced to leaf
        children = [None] * n

        for i in range(n):
            parts = lines[idx].strip().split()
            idx += 1
            if parts[0] == '-1':
                children[i] = (int(parts[1]), int(parts[2]))
            else:
                values[i] = int(parts[0])
                children[i] = None

        # Compute L values (number of leaves in subtree)
        # Process nodes bottom-up or use memoization
        def get_left_count(u):
            if children[u] is None:
                return 1
            left, right = children[u]
            return get_left_count(left) + get_left_count(right)

        # Compute value for each internal node
        def compute_value(u):
            if children[u] is None:
                return values[u]
            left, right = children[u]
            left_val = compute_value(left)
            right_val = compute_value(right)
            if get_left_count(u) % 2 == 0:
                return max(left_val, right_val)
            else:
                return min(left_val, right_val)

        result = compute_value(0)
        results.append(str(result))

    return '\n'.join(results)

from typing import List

def count_matches(code1: str, code2: str) -> int:
    """Count positions where two codes match."""
    return sum(1 for a, b in zip(code1, code2) if a == b)

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempts.append((parts[0], int(parts[1])))

    # Generate candidates from first attempt by choosing positions to flip
    first_s, first_c = attempts[0]

    candidates = set()

    # Generate all codes that match first attempt in exactly first_c positions
    # This means we need to flip (n - first_c) bits
    if n - first_c <= 0:
        # All bits must stay same - there's only one candidate
        candidates.add(first_s)
    else:
        # Iterate through all combinations of positions to flip
        from itertools import combinations, combinations_with_replacement

        for flip_positions in combinations(range(n), n - first_c):
            candidate = list(first_s)
            for pos in flip_positions:
                candidate[pos] = '1' if candidate[pos] == '0' else '0'
            candidates.add(''.join(candidate))

    # Count how many candidates satisfy all constraints
    count = 0
    for candidate in candidates:
        valid = True
        for s, c in attempts:
            if count_matches(candidate, s) != c:
                valid = False
                break
        if valid:
            count += 1

    return str(count)

