    max_val = max(max(a) if a else 0, max(b) if b else 0)

    # Prefix sum for each value v
    # prefix[v][i] = sum of p[j] for j < i where a[j] >= v
    prefix = {}
    for v in range(1, max_val + 1):
        pg = [0] * (n + 1)
        for i in range(n):
            pg[i+1] = pg[i]
            if a[i] >= v:
                pg[i+1] += p[i]
        prefix[v] = pg

    INF = float('inf')

    # dp[val][pos] = minimum cost to match a prefix of b ending with that value at position pos
    # We use a dictionary to only store reachable states

    # For b[0]: cost = prefix[b[0]][pos] for each pos in positions[b[0]]
    dp_prev = {}
    for pos in positions[b[0]]:
        cost = prefix[b[0]][pos]
        dp_prev[pos] = cost

