    for i in range(1, m):
        prev_val = b[i-1]
        curr_val = b[i]
        dp_curr = {}
        curr_min = INF

        # For each position of the current value in a
        for curr_pos in positions[curr_val]:
            # For each valid previous position
            best_prev = INF
            for prev_pos in dp_prev:
                if prev_pos < curr_pos:
                    # Transition cost: dp[prev_pos] + (prefix[curr_val][curr_pos] - prefix[curr_val][prev_pos])
                    cost = dp_prev[prev_pos] + prefix[curr_val][curr_pos] - prefix[curr_val][prev_pos]
                    if cost < best_prev:
                        best_prev = cost

            if best_prev < INF:
                cost = best_prev + prefix[curr_val][curr_pos] - prefix[curr_val][curr_pos]
                if cost < INF:
                    dp_curr[curr_pos] = cost

        # Optimization: keep only minimum cost positions within the same value group
        # Actually, we need all positions for future matching

        dp_prev = dp_curr
        if not dp_prev:
            return "NO"

    # After matching all of b, compute final cost for each ending position
    # Add remaining elements deletion cost
    ans = INF
    for last_pos, cost in dp_prev.items():
        remaining = prefix[b[-1]][n] - prefix[b[-1]][last_pos + 1]
