def cross_product(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def on_segment(p, a, b):
    if min(a[0], b[0]) > p[0] > max(a[0], b[0]):
        return False
    if min(a[1], b[1]) > p[1] > max(a[1], b[1]):
        return False
    return True

def segments_intersect(a, b, c, d):
    cp1 = cross_product(c, d, a)
    cp2 = cross_product(c, d, b)
    cp3 = cross_product(a, b, c)
    cp4 = cross_product(a, b, d)

    if ((cp1 > 0 and cp2 < 0) or (cp1 < 0 and cp2 > 0)) and \
       ((cp3 > 0 and cp4 < 0) or (cp3 < 0 and cp4 > 0)):
        return True

    if cp1 == 0 and (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= c[1] <= max(a[1], b[1])):
        return True
    if cp2 == 0 and (min(a[0], b[0]) <= d[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= d[1] <= max(a[1], b[1])):
        return True
    if cp3 == 0 and (min(c[0], d[0]) <= a[0] <= max(c[0], d[0]) and min(c[1], d[1]) <= a[1] <= max(c[1], d[1])):
        return True
    if cp4 == 0 and (min(c[0], d[0]) <= b[0] <= max(c[0], d[0]) and min(c[1], d[1]) <= b[1] <= max(c[1], d[1])):
        return True

    return False

def is_valid_for_dp(i, j, n, p):
    di1 = (j - i) % n
    di2 = (n - di1) % n

    if di1 == 1 or di2 == 1:
        return True

    for start in range(n):
        end = (start + 1) % n
        if start == 0 and end == n - 1:
            continue
        if start == i or end == i or start == j or end == j:
            continue
        if segments_intersect(p[i], p[j], p[start], p[end]):
            return False

    return True

