    MOD = 1000000007

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    p = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        p.append((x, y))

    if n == 3:
        return "1\n"

    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i + 1] = 1

    for length in range(2, n):
        for i in range(n - length):
            j = (i + length) % n
            if i + j >= n + 1:
                continue

            dp[i][j] = 0
            for k in range(i + 1, j):
                if is_valid_for_dp(i, k, n, p) and is_valid_for_dp(k, j, n, p):
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

    result = dp[0][n - 1]
    return f"{result}\n"

