            ft = fall_times[pos-1]
            if ft not in fall_event_map:
                fall_event_map[ft] = []
            fall_event_map[ft].append(pos)

        # Get all distinct fall times
        all_times = sorted(fall_event_map.keys())

        # Find minimum entrapment time
        min_t = n + 1

        # Check each candidate time
        for t in all_times:
            # Get all fallen icicles by time t
