def solution(input_str):
    lines = input_str.strip().split('\n')
    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])
    guests = list(map(int, lines[2].split()))

    def simulate(arrival):
        """
        Simulate the queue when Vasya arrives at 'arrival' time.
        Returns the queue time for Vasya. Returns -1 if Vasya cannot be served.
        """
        # Track when receptionist finishes serving existing guests
        finish_after_guests = ts

        for guest_arr in guests:
            # Guest starts when both ready: max(guest arrival, when receptionist is free)
            start = max(guest_arr, finish_after_guests)
            finish_after_guests = start + t
            # Skip if service would exceed closure time
            if finish_after_guests > tf:
                return -1

        # Vasya's turn now
        start = max(arrival, finish_after_guests)
        finish = start + t

        if finish > tf:
            return -1

        # Queue time = time between arrival and when service begins
        queue_time = start - arrival
        return queue_time

    # For each valid arrival time, track minimum queue time
    best_arrival = ts
    min_queue = float('inf')

    # Try arrival at ts (guaranteed to be valid)
    queue = simulate(ts)
    if queue != -1:
        min_queue = queue
        best_arrival = ts

    # Check other candidate times before ts
    for arrv in list(range(ts + 1)):
        q = simulate(arrv)
        if q != -1:
            min_queue = min(min_queue, q)

    # If ts gives minimal queue, verify if we should return earliest or any
    # Since we want ANY valid answer that minimizes queue, and ts has minimal queue
    if min_queue == 0:
        # Return the earliest valid arrival that gets queue time 0
        for arrv in range(ts + 1):
            if simulate(arrv) == 0:
                return str(arrv)

    return str(best_arrival)

def solution_fully(input_str):
