    def simulate(arrival):
        finish_after_guests = ts
        for guest_arr in guests:
            start = max(guest_arr, finish_after_guests)
            finish_after_guests = start + t
            if finish_after_guests > tf:
                return -1
        start = max(arrival, finish_after_guests)
        finish = start + t
        if finish > tf:
            return -1
        queue_time = start - arrival
        return queue_time

    best_arrival = None
    min_queue = float('inf')

    # Check all practical candidate arrival times
    candidates = set()
    candidates.add(ts)
    candidates.add(0)
    for g in guests:
        candidates.add(g)
        if g >= ts:
            candidates.add(ts + g // 2 + ts // 2)

    for arrv in sorted(candidates):
        if arrv < 0:
            continue
        q = simulate(arrv)
        if q == 0:
            best_arrival = min(arrival if (best_arrival is not None) else arrv)
            continue
        if q != -1:
            if q < min_queue:
                min_queue = q
                best_arrival = arrv
            elif q == min_queue:
                if best_arrival is None or arrv < best_arrival:
                    best_arrival = arrv

    if best_arrival is None:
        # Fall back to ts
        return str(ts)

    return str(best_arrival)

