        divs = []
        for i in range(1, int(x**0.5) + 1):
            if x % i == 0:
                divs.append(i)
                if i * i != x:
                    divs.append(x // i)
        return sorted(divs)

    divs_n = get_divisors(n)
    divs_m = get_divisors(m)

    # Find the largest row period r0 (largest r such that rows repeat with period r)
    def find_max_row_period():
        if n <= 1:
            return 1

        # Binary search over divisors
        divs = sorted(divs_n, reverse=True)

        for r in divs:
            # Check if rows repeat with period r
            valid = True
            for i in range(1, n - r + 1):
                if not query(1, m, i, 1, i + r, 1):
                    valid = False
                    break
            if valid:
                return r
        return 1

    # Find the largest column period c0
    def find_max_col_period():
        if m <= 1:
            return 1

        divs = sorted(divs_m, reverse=True)

        for c in divs:
            valid = True
            for j in range(1, m - c + 1):
                if not query(n, 1, 1, j, 1, j + c):
                    valid = False
                    break
            if valid:
                return c
        return 1

    row_period = find_max_row_period()
    col_period = find_max_col_period()

    # Count valid pairs: divisors of row_period that divide n, 
    # AND divisors of col_period that divide m
    ans = 0
    for r in divs_n:
        if n % r == 0 and row_period % r == 0:
            for c in divs_m:
                if m % c == 0 and col_period % c == 0:
                    ans += 1

    output = f"! {ans}"
