def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    frogs = []
    for i in range(n):
        p, a = map(int, lines[i + 1].split())
        frogs.append({'id': i + 1, 'pos': p, 'a': a, 'alive': True})

    active = set(range(n))  # indices of active frogs
    turn = 0  # current turn (0-indexed)

    while active:
        frog_idx = turn % n

        while frog_idx not in active:
            turn += 1
            frog_idx = turn % n

        frog = frogs[frog_idx]

        if frog['a'] <= 0:
            # This frog stops moving
            active.remove(frog_idx)
            turn += 1
            continue

        # Calculate destination (1-indexed, cyclic)
        current_pos = frog['pos']
        dest = (current_pos - 1 + frog['a']) % m + 1

        # Check for frogs on the path (start to end inclusive)
        # Path includes all cells from current_pos through dest
        path_start = current_pos
        path_end = dest

        knocked_count = 0

        if path_start <= path_end:
            # Simple range: [path_start, path_end]
            for i in range(path_start, path_end + 1):
                if i in [(frogs[j]['pos']) for j in active if j != frog_idx]:
                    # Check if any active frog is at this position
                    for other_idx in list(active - {frog_idx}):
                        if frogs[other_idx]['pos'] == i:
                            knocked_count += 1
                            frogs[other_idx]['alive'] = False
                            active.remove(other_idx)
        else:
            # Wrapping around: [path_start, m] and [1, path_end]
            for i in range(path_start, m + 1):
                for other_idx in list(active - {frog_idx}):
                    if frogs[other_idx]['pos'] == i:
                        knocked_count += 1
                        frogs[other_idx]['alive'] = False
                        active.remove(other_idx)
            for i in range(1, path_end + 1):
                for other_idx in list(active - {frog_idx}):
                    if frogs[other_idx]['pos'] == i:
                        knocked_count += 1
                        frogs[other_idx]['alive'] = False
                        active.remove(other_idx)

        # Update frog position and jump length
        frog['pos'] = dest
        frog['a'] -= knocked_count

        turn += 1

    # Get remaining frogs
    result_ids = sorted([frogs[i]['id'] for i in active])
    output_lines = [str(len(result_ids)), ' '.join(map(str, result_ids))]
    return '\n'.join(output_lines)

