                    var2 = abs(lits[j])
                    union2(var1, var2)

    # Use path compression for find
    def find_path(x):
        stack = [x]
        while parent[stack[-1]] != stack[-1]:
            stack.append(parent[stack[-1]])
        root = stack[-1]
        while stack:
            parent[stack.pop()] = root
        return root

    # Process find with proper path compression
    parent = list(range(m + 1))
    def get_root(x):
        if parent[x] != x:
            parent[x] = get_root(parent[x])
        return parent[x]

    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        if len(parts) > 0 and parts[0] >= 2:
            lits = parts[1:]
            if len(lits) >= 2:
                for j in range(1, len(lits)):
                    var1 = abs(lits[0])
                    var2 = abs(lits[j])
                    r1, r2 = get_root(var1), get_root(var2)
                    if r1 != r2:
                        parent[r1] = r2

    # Now count variables per component and edges per component
    comp_vars = {}  # root -> count of variables in component
    comp_edges = {}  # root -> count of clauses in component

    # Count variables in each component
    for var in range(1, m + 1):
        if get_root(var) == var:
            comp_vars[var] = 0
        elif var in var_occ and len(var_occ[var]) > 0:
            root = get_root(var)
            if root not in comp_vars:
                comp_vars[root] = 0
            comp_vars[root] += 1

    # Count edges (clauses) in each component
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        k = parts[0]
        if k >= 2:
            lits = parts[1:]
            # The clause connects variables, so check which component the clause belongs to
            if len(lits) >= 2:
                var1 = abs(lits[0])
                var2 = abs(lits[1])
                root = get_root(var1)
                if root not in comp_edges:
                    comp_edges[root] = 0
                comp_edges[root] += 1

    ans = 1

    # For each component, compute the contribution
    for root in list(comp_vars.keys()):
        v = comp_vars[root]
        e = comp_edges.get(root, 0)

        # Determine the structure (cycle or tree)
        # If e == v, it's a cycle; if e == v - 1, it's a tree
        if e == v:
            # Cycle: contributes 2^(v-1)
            contribution = pow(2, v - 1, MOD)
        else:
            # Tree: contributes 2^(v-1) when satisfying XOR
            contribution = pow(2, v - 1, MOD)

        ans = (ans * contribution) % MOD

    # Variables not in any clause contribute 2 each
    factors_of_2 = 0
    for var in range(1, m + 1):
        if var not in var_occ or len(var_occ[var]) == 0:
            factors_of_2 += 1

    ans = (ans * pow(2, factors_of_2, MOD)) % MOD

    return str(ans) + '\n'


